function seasonFixture(int $minutes,int $goals,int $assists=0):array{$g=Game::legacyCreate('Fixture mercado','São Paulo','SP','centroavante');$g['season']=3;$template=$g['matches'][Game::currentIndex($g)];$g['matches']=[];$left=$minutes;for($i=0;$left>0;$i++){$m=$template;$played=min(90,$left);$left-=$played;$m['round']=$i+1;$m['status']='finalizada';$m['stats']=array_replace($m['stats'],['minutes'=>$played,'goals'=>$i===0?$goals:0,'assists'=>$i===0?$assists:0,'rating'=>7.5,'tackles'=>$i===0?5:0,'shots'=>$i===0?max(10,$goals):0]);$g['matches'][]=$m;}return $g;}

