$def=$g;$def['position']='zagueiro';marketCheck(SeasonEvaluation::current($def)['score']!==SeasonEvaluation::current($g)['score'],'Posições têm avaliação própria');
$g=seasonFixture(1500,10);$before=$g;$draws=[];for($n=0;$n<100;$n++){$window=$g;$window['stage']='resumo';$window=Game::command($window,'offers');$draw=$window['market_draw'];$closed=Game::command($window,'transfer',count($window['offers'])&&$n%2?['accept'=>'yes','option'=>0]:['accept'=>'no']);marketCheck($closed['season']===$g['season']+1&&count($closed['history'])===1,'Fechamento isolado completo');$count=count($draw['offers']);$draws[$draw['scenario']]=($draws[$draw['scenario']]??0)+1;marketCheck($count>=0&&$count<=3,'Zero a três ofertas');marketCheck(count(array_unique(array_column($draw['offers'],'club')))===$count,'Clubes distintos');marketCheck($draw['stay']['club']===$g['club'],'Permanência sempre disponível');foreach($draw['offers'] as $o)marketCheck(in_array($o['club'],Rules::TEAMS,true),'Sem clube inventado em carreira legada');$copy=json_decode(json_encode($draw),true);marketCheck($copy['id']===$draw['id']&&$copy['scenario']===$draw['scenario'],'Snapshot de mercado serializável');}
marketCheck($g===$before,'Calcular não altera save');
$low=$g;$high=$g;foreach($low['skills'] as &$s)$s['value']=30;unset($s);foreach($high['skills'] as &$s)$s['value']=85;unset($s);$fLow=OpportunityForecast::estimate($low,$g['club']);$fHigh=OpportunityForecast::estimate($high,$g['club']);marketCheck($fHigh['minutes_percent']>$fLow['minutes_percent'],'Melhor atleta recebe projeção maior');marketCheck($fHigh['expected_minutes']<=$fHigh['scheduled_games']*90,'Minutos limitados ao calendário');
$g['stage']='resumo';$g=Game::command($g,'offers');marketCheck(($g['market_draw']['schema']??0)===2,'Comando salva novo mercado');$snapshot=$g;try{Game::command($g,'transfer',['accept'=>'yes','option'=>99]);marketCheck(false,'Índice forjado aceito');}catch(InvalidArgumentException){marketCheck($g===$snapshot,'Rejeição não muda save');}$stay=Game::command($g,'transfer',['accept'=>'no']);marketCheck($stay['club']===$g['club']&&$stay['season']===$g['season']+1,'Ficar avança uma temporada');marketCheck(isset($stay['history'][0]['evaluation'],$stay['history'][0]['market']['choice']),'Histórico preserva avaliação e escolha');
$official=$g;$official['official']=true;$official['club']=Competition::catalog()['br-b']['teams'][0];$official['memberships']=array_map(fn($c)=>$c['teams'],Competition::catalog());$official['season_competitions']=['br-b'];$official['competition_id']='br-b';foreach($official['matches'] as &$match){$match['home']=$official['club'];$match['away']=Competition::catalog()['br-b']['teams'][1];}unset($match);
