foreach($official['matches'] as &$match)$match['stats']['rating']=9.5;unset($match);$official['matches'][0]['stats']['goals']=15;
$eliteEvaluation=SeasonEvaluation::evaluate($official);$eliteCandidates=TransferMarket::pool($official,false);$seven=TransferInterest::scenarios($official,$eliteCandidates,$eliteEvaluation);$forced=[];
