$projection=$official;$projection['next_club_strengths'][$projection['club']]=78.4;$projectedDraw=TransferInterest::draw($projection);marketCheck($projectedDraw['stay']['overall']===78.4,'Permanência usa a mesma referência da próxima temporada que as diferenças das propostas');
